package com.aifacemate.face.voice.tts.client
import com.aifacemate.face.network.NetworkClient
import com.aifacemate.face.voice.tts.internal.base64Decode
import com.aifacemate.face.voice.tts.catalog.defaultTtsProviders
import com.aifacemate.face.voice.tts.internal.jsonEscape
import com.aifacemate.face.voice.tts.model.TtsRequest
import com.aifacemate.face.voice.tts.model.TtsResult
class TtsClient(private val network: NetworkClient) { suspend fun synthesize(request:TtsRequest):TtsResult {if(request.apiKey.isBlank())return TtsResult.Failure("请先填写 TTS API Key");if(request.text.isBlank())return TtsResult.Failure("请输入要合成的文字");val provider=defaultTtsProviders.firstOrNull{it.id==request.providerId}?:return TtsResult.Failure("不支持的 TTS 供应商：${request.providerId}");val body="{\"model\":\"${jsonEscape(request.model)}\",\"messages\":[{\"role\":\"user\",\"content\":\"\"},{\"role\":\"assistant\",\"content\":\"${jsonEscape(request.text)}\"}],\"audio\":{\"format\":\"${jsonEscape(request.format)}\",\"voice\":\"${jsonEscape(request.voice)}\"},\"stream\":false}";val endpoint="${request.baseUrl?:provider.baseUrl}/chat/completions";val response=network.postJson(endpoint,mapOf("api-key" to request.apiKey.trim()),body);if(response.statusCode !in 200..299)return TtsResult.Failure("TTS 请求失败（HTTP ${response.statusCode}）",response.statusCode);val encoded=Regex("\\\"audio\\\"\\s*:\\s*\\{[^}]*\\\"data\\\"\\s*:\\s*\\\"([^\"]+)\\\"").find(response.text)?.groupValues?.get(1);return if(encoded.isNullOrBlank())TtsResult.Failure("TTS 返回格式无法解析",response.statusCode)else TtsResult.Success(encoded.base64Decode(),"audio/${request.format}")} }
